import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Loading and overrides: find the effective value","description":"Understand the priority of defaults, environment variables, and database runtime settings, including when an API or Worker restart is required.","frontmatter":{"page_id":"configuration-loading-overrides","title":"Loading and overrides: find the effective value","description":"Understand the priority of defaults, environment variables, and database runtime settings, including when an API or Worker restart is required."},"headers":[],"relativePath":"en/configuration/loading-and-overrides.md","filePath":"en/configuration/loading-and-overrides.md","lastUpdated":1786627803000}'),n={name:"en/configuration/loading-and-overrides.md"};function r(o,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="loading-and-overrides-find-the-effective-value" tabindex="-1">Loading and overrides: find the effective value <a class="header-anchor" href="#loading-and-overrides-find-the-effective-value" aria-label="Permalink to &quot;Loading and overrides: find the effective value&quot;">​</a></h1><p>The same setting can appear as a default, in <code>.env</code>, in the process environment, and in the database. This page explains which value wins and when a change takes effect.</p><h2 id="separate-two-kinds-of-settings" tabindex="-1">Separate two kinds of settings <a class="header-anchor" href="#separate-two-kinds-of-settings" aria-label="Permalink to &quot;Separate two kinds of settings&quot;">​</a></h2><p>Ershu backend settings fall into two groups:</p><ol><li><strong>Startup settings</strong> are created and cached inside the process. Restart the affected process after changing their environment values.</li><li><strong>Runtime-overridable settings</strong> start with an environment value, then allow a database row named <code>runtime.&lt;name&gt;</code> to take priority. New operations use the database value after the service refreshes runtime settings.</li></ol><p>A database override does not rewrite <code>.env</code>. Deleting the row returns to the environment value captured when the process started; there is no second stored copy of that environment value.</p><h2 id="precedence-from-lowest-to-highest" tabindex="-1">Precedence from lowest to highest <a class="header-anchor" href="#precedence-from-lowest-to-highest" aria-label="Permalink to &quot;Precedence from lowest to highest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priority</th><th>Source</th><th>Meaning</th></tr></thead><tbody><tr><td>1</td><td>Settings-class default</td><td>Used only when no other source supplies a value</td></tr><tr><td>2</td><td><code>.env</code></td><td>The settings classes declare a file named <code>.env</code></td></tr><tr><td>3</td><td>Process environment</td><td>Deployment-injected values take priority over matching <code>.env</code> values</td></tr><tr><td>4</td><td>Database runtime setting</td><td>Applies only to registered runtime settings, using the key <code>runtime.&lt;name&gt;</code></td></tr></tbody></table><p>Both API <code>get_api_settings()</code> and Core <code>get_settings()</code> are cached in memory. Restart the affected process after changing a non-runtime value such as <code>DATABASE_URL</code>, <code>REDIS_URL</code>, <code>CORS_ORIGINS</code>, or any server secret.</p><h2 id="values-the-api-process-can-override-at-runtime" tabindex="-1">Values the API process can override at runtime <a class="header-anchor" href="#values-the-api-process-can-override-at-runtime" aria-label="Permalink to &quot;Values the API process can override at runtime&quot;">​</a></h2><p>The API process reads ten Core runtime settings and adds one API-owned setting for chat stream-ticket lifetime.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Environment variable</th><th>Accepted value</th><th>Applied to</th></tr></thead><tbody><tr><td><code>run_queue_lease_timeout_seconds</code></td><td><code>RUN_QUEUE_LEASE_TIMEOUT_SECONDS</code></td><td>300–86400</td><td>New recovery scans and heartbeat intervals</td></tr><tr><td><code>analysis_run_retention_count</code></td><td><code>ANALYSIS_RUN_RETENTION_COUNT</code></td><td>1–10000</td><td>Per-project history cleanup when runs finish or maintenance runs</td></tr><tr><td><code>search_index_batch_size</code></td><td><code>SEARCH_INDEX_BATCH_SIZE</code></td><td>100–20000</td><td>New index rebuild batches</td></tr><tr><td><code>git_command_timeout_seconds</code></td><td><code>GIT_COMMAND_TIMEOUT_SECONDS</code></td><td>10–3600</td><td>Later Git commands and cache-lock waits</td></tr><tr><td><code>repository_storage_path</code></td><td><code>REPOSITORY_STORAGE_PATH</code></td><td>Non-empty string, at most 255 characters</td><td>Later repository cache access</td></tr><tr><td><code>trusted_local_paths</code></td><td><code>TRUSTED_LOCAL_PATHS</code></td><td>At most 50 strings</td><td>Later local-workspace authorization</td></tr><tr><td><code>allow_dev_open_local_repository_paths</code></td><td><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code></td><td>Boolean</td><td>Later local-workspace authorization</td></tr><tr><td><code>git_allowed_hosts</code></td><td><code>GIT_ALLOWED_HOSTS</code></td><td>At most 50 strings</td><td>Later remote-repository URL checks</td></tr><tr><td><code>allow_insecure_git_urls</code></td><td><code>ALLOW_INSECURE_GIT_URLS</code></td><td>Boolean</td><td>Later repository URL checks</td></tr><tr><td><code>allow_file_git_urls</code></td><td><code>ALLOW_FILE_GIT_URLS</code></td><td>Boolean</td><td>Later repository URL checks</td></tr><tr><td><code>stream_ticket_expire_seconds</code></td><td><code>STREAM_TICKET_EXPIRE_SECONDS</code></td><td>30–3600</td><td>Newly issued chat stream tickets</td></tr></tbody></table><p>“Later” is significant. Changing the repository path does not move an existing cache, and changing a ticket lifetime does not rewrite tickets that have already been issued.</p><h2 id="why-the-administration-api-lists-48-settings" tabindex="-1">Why the administration API lists 48 settings <a class="header-anchor" href="#why-the-administration-api-lists-48-settings" aria-label="Permalink to &quot;Why the administration API lists 48 settings&quot;">​</a></h2><p><code>GET /api/v1/admin/system-settings</code> combines three definition groups:</p><ul><li>10 Core runtime settings;</li><li>37 Worker runtime settings;</li><li>1 API runtime setting.</li></ul><p>The API validates and stores all 48 and reports <code>environment_value</code>, effective <code>value</code>, and <code>source</code> for each. The API process applies only Core and API definitions to itself. Each Worker must refresh the Core and Worker definitions through its own lifecycle. A successful administration response does not prove that every running Worker has refreshed.</p><p>Administrators manage overrides through three endpoints:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Endpoint</th><th>Result</th></tr></thead><tbody><tr><td>Read</td><td><code>GET /api/v1/admin/system-settings</code></td><td>Returns definitions, environment values, effective values, and sources</td></tr><tr><td>Update</td><td><code>PATCH /api/v1/admin/system-settings</code></td><td>Validates and writes database rows, then records an audit event</td></tr><tr><td>Reset</td><td><code>DELETE /api/v1/admin/system-settings/{name}</code></td><td>Removes one database override and returns to its environment value</td></tr></tbody></table><p>Only administrators can call these endpoints. Unknown names, wrong types, out-of-range integers, and oversized lists are rejected as input errors instead of leaving an ambiguous partial configuration.</p><h2 id="when-a-change-takes-effect" tabindex="-1">When a change takes effect <a class="header-anchor" href="#when-a-change-takes-effect" aria-label="Permalink to &quot;When a change takes effect&quot;">​</a></h2><p>The API refreshes once during startup and then reads database overrides every 30 seconds. The administration service rereads settings immediately after an update or reset and returns that current state. New API operations normally see a just-saved Core or API value immediately; other API instances see it no later than their next successful refresh.</p><p>If a periodic refresh fails, the API logs the error and continues to the next cycle. A row inserted by an external database tool can fail decoding or range validation. Repair it through the administration endpoint or remove the corresponding <code>runtime.&lt;name&gt;</code> row.</p><p>Worker timing is controlled by Worker refresh points. Do not infer that a Worker updates on the API&#39;s 30-second schedule.</p><h2 id="verify-the-active-source-in-the-response" tabindex="-1">Verify the active source in the response <a class="header-anchor" href="#verify-the-active-source-in-the-response" aria-label="Permalink to &quot;Verify the active source in the response&quot;">​</a></h2><p>Read the target item again after an update:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;git_command_timeout_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;env_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GIT_COMMAND_TIMEOUT_SECONDS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">180</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;environment_value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;database&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>This example documents the response fields; it is not a captured local command result. Interpret it as follows:</p><ul><li><code>source: environment</code> means there is no database override, so <code>value</code> should equal <code>environment_value</code>;</li><li><code>source: database</code> means an override is active, and the two values may differ;</li><li>after a reset and reread, <code>source</code> should return to <code>environment</code>;</li><li>after changing a non-runtime environment value, restart the affected process so its cached settings are rebuilt.</li></ul><h2 id="source-locations" tabindex="-1">Source locations <a class="header-anchor" href="#source-locations" aria-label="Permalink to &quot;Source locations&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>: <code>.env</code> declaration, Core settings, and cached settings entry point.</li><li><code>core/src/ershu/services/runtime_settings.py</code>: Core runtime definitions, database keys, value validation, refresh, and override application.</li><li><code>core/src/ershu/services/worker_runtime_contract.py</code>: the 37 Worker administration definitions.</li><li><code>api/src/ershu/api/runtime_settings.py</code>: API settings, stream-ticket definition, and API refresh entry point.</li><li><code>api/src/ershu/api/services/system_settings.py</code>: the 48-setting union, source reporting, updates, and resets.</li><li><code>api/src/ershu/api/routes/system_settings.py</code>: administrator endpoints and authorization dependency.</li><li><code>api/src/ershu/api_main.py</code>: startup refresh and the API&#39;s 30-second refresh loop.</li><li><code>worker/src/ershu/workers/runtime_settings.py</code>: Worker entry points for applying Core and Worker runtime settings.</li></ul>`,31)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
